const input = $json.body ?? $json;

const text = (value) => {
  if (value === null || value === undefined) return '';
  return String(value).trim();
};

const toBoolean = (value) => {
  if (typeof value === 'boolean') return value;
  return ['true', '1', 'yes', 'on'].includes(text(value).toLowerCase());
};

const clinic_name = text(input.clinic_name);
const clinical_intake_case_id =
  Number(input.clinical_intake_case_id);
const action = text(input.action).toLowerCase();
const actor_name = text(input.actor_name);
const service_name = text(input.service_name);
const response_to_patient = text(input.response_to_patient);
const resolution_note = text(input.resolution_note);
const confirm_action = toBoolean(input.confirm_action);

const actions = [
  'claim',
  'request_more_information',
  'route_to_service',
  'escalate_to_doctor',
  'resolve',
  'close',
];

const errors = [];

if (!clinic_name) {
  errors.push({
    field: 'clinic_name',
    message: 'نام کلینیک الزامی است.',
  });
}

if (
  !Number.isInteger(clinical_intake_case_id) ||
  clinical_intake_case_id < 1
) {
  errors.push({
    field: 'clinical_intake_case_id',
    message: 'شناسه پرونده معتبر نیست.',
  });
}

if (!actions.includes(action)) {
  errors.push({
    field: 'action',
    message: 'اقدام درخواستی معتبر نیست.',
  });
}

if (!actor_name) {
  errors.push({
    field: 'actor_name',
    message: 'نام مسئول انجام اقدام الزامی است.',
  });
}

if (
  action === 'route_to_service' &&
  !service_name
) {
  errors.push({
    field: 'service_name',
    message: 'برای مسیریابی، نام خدمت الزامی است.',
  });
}

if (
  action === 'request_more_information' &&
  !response_to_patient
) {
  errors.push({
    field: 'response_to_patient',
    message: 'متن درخواست اطلاعات بیشتر الزامی است.',
  });
}

if (
  ['resolve', 'close'].includes(action) &&
  !resolution_note
) {
  errors.push({
    field: 'resolution_note',
    message: 'برای بستن یا حل پرونده، توضیح نتیجه الزامی است.',
  });
}

if (confirm_action !== true) {
  errors.push({
    field: 'confirm_action',
    message: 'انجام اقدام باید به‌صورت صریح تأیید شود.',
  });
}

return [{
  json: {
    clinic_name,
    clinical_intake_case_id,
    action,
    actor_name,
    service_name,
    response_to_patient,
    resolution_note,
    confirm_action,
    validation_status: errors.length === 0 ? 'valid' : 'invalid',
    errors,
  },
}];

return [{
  json: {
    success: false,
    result: 'invalid_request',
    message: 'اطلاعات اقدام انسانی ناقص یا نامعتبر است.',
    errors: $json.errors ?? [],
  },
}];
